First, create a `TooltipContext` to store the state of the currently opened Tooltip and a function to close it.

```jsx
import React, { createContext, useState } from 'react';

export const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltipOpen, setTooltipOpen] = useState(false);
  const [tooltipData, setTooltipData] = useState(null);

  const closeTooltip = () => {
    setTooltipOpen(false);
    setTooltipData(null);
  };

  const value = { tooltipOpen, tooltipData, closeTooltip };

  return (
    <TooltipContext.Provider value={value}>
      {children}
      {tooltipOpen && <Tooltip data={tooltipData} />}
    </TooltipContext.Provider>
  );
};
```

Then, create the `Tooltip` component that will be displayed when the tooltip is open.

```jsx
import React from 'react';

const Tooltip = ({ data }) => {
  return (
    <div className="tooltip">
      <div className="tooltip-arrow" />
      <div className="tooltip-content">{data}</div>
    </div>
  );
};

export default Tooltip;
```

Finally, use the `TooltipProvider` and `Tooltip` components in your NextJS project.

```jsx
import React, { useContext } from 'react';
import TooltipProvider from '../components/TooltipProvider';
import Tooltip from '../components/Tooltip';

const MyComponent = () => {
  const { tooltipOpen, closeTooltip } = useContext(TooltipContext);

  const handleMouseOver = (data) => {
    setTooltipOpen(true);
    setTooltipData(data);
  };

  const handleMouseLeave = () => {
    closeTooltip();
  };

  return (
    <div
      onMouseOver={() => handleMouseOver('Hello, Tooltip!')}
      onMouseLeave={handleMouseLeave}
    >
      Hover over me!
    </div>
  );
};

export default function Page() {
  return (
    <TooltipProvider>
      <MyComponent />
    </TooltipProvider>
  );
}
```

Now, when you hover over the `MyComponent`, the Tooltip will be displayed, and when you move the mouse away, it will be closed. The previously opened Tooltip will also be closed when a new one is opened.

